'DD-MM-YYYY\'), TRY_TO_DATE(TRIM(spf.MONTH), \'DD-MON-YYYY\'), TRY_TO_DATE(TRIM(spf.MONTH), \'MON-YY\'), TRY_TO_DATE(TRIM(spf.MONTH), \'MM-YYYY\'), TRY_TO_DATE(TRIM(spf.MONTH), \'MON-YYYY\') ) AS QCd_month, COALESCE( TRY_TO_TIME(REGEXP_REPLACE(QC_DONE_DATE, \'[;.]\', \':\'), \'HH12:MI AM\'), TRY_TO_TIME(REGEXP_REPLACE(QC_DONE_DATE, \'[;.]\', \':\'), \'HH24:MI\') ) AS QC_time, CASE WHEN UPPER(TRIM(spf.channel_name)) IN (\'SHOPIFY\', \'B2C-DELHIVERY\', \'B2C-PROZO\', \'B2C-EKART\', \'B2C PROZO\', \'B2C-BLUEDART\', \'B2C-BLITZ\') THEN \'SHOPIFY\' WHEN UPPER(TRIM(spf.channel_name)) IN (\'SAPL_AJIO_OMNI_2\', \'SAPL_AJIO_OMNI_EMIZA\', \'SAPL_AJIO_OMNI\', \'AJIO\', \'MP_AJIO\') THEN \'AJIO\' WHEN UPPER(TRIM(spf.channel_name)) IN (\'FLIPKART_SAPLWH2\', \'FLIPKART_SAPL\', \'FLIPKART\',\'MP-FLIPKART\', \'FLIPKART_SAPL_EMIZA\') THEN \'FLIPKART\' WHEN UPPER(TRIM(spf.channel_name)) IN (\'MYNTRAPMP_SAPL-WH2\', \'SAPL_MYNTAPPMP\',\'SAPL_MYNTRAPPMP\', \'MP-MYNTRA\', \'SAPL_MYNTAPP_EMIZA\',\'MYNTRAPPMP_SAPL-WH2\',\'SAPL_MYNTRA_EMIZA\',\'MYNTRA\') THEN \'MYNTRA\' WHEN UPPER(TRIM(spf.channel_name)) IN (\'AMAZON_FLEX_WH2\', \'AMAZON_FLEX_API_SAPL\', \'MP-AMAZON\', \'AMAZON\') THEN \'AMAZON\' WHEN UPPER(TRIM(spf.channel_name)) IN (\'MP-NYKAA\', \'NYKAA_FASHION_WH2\', \'NYKAA_FASHION_WH\', \'NYKAA_COM_SAPLWH\',\'NYKAA_COM_WH2\', \'NYKAA\') THEN \'NYKAA\' WHEN UPPER(TRIM(spf.channel_name)) IN (\'MP-CRED\') THEN \'CRED\' WHEN UPPER(TRIM(spf.channel_name)) IN (\'GROO SHIP\') THEN \'GROO SHIP\' WHEN UPPER(TRIM(spf.channel_name)) IN (\'DONOSHOP\') THEN \'DONOSHOP\' WHEN UPPER(TRIM(spf.channel_name)) IN (\'BLUEDART\') THEN \'BLUEDART\' WHEN UPPER(TRIM(spf.channel_name)) IN (\'SELFSHIP\') THEN \'SELFSHIP\' END AS channel_name, NULLIF(LOWER(TRIM(r2i.LM_PATNER)), \'null\') AS LM_PARTNER, NULLIF(LOWER(TRIM(r2i.QC_TYPE)), \'null\') AS QC_TYPE, NULLIF(LOWER(TRIM(spf.shipment_type)), \'null\') AS shipment_type, NULLIF(LOWER(TRIM(r2i.REMARKS)), \'null\') AS R2I_REMARKS, TRY_TO_DATE(spf.fake_raised_date, \'DD-MM-YYYY\') AS fake_raised_date, CASE WHEN UPPER(TRIM(spf.DONE_BY)) IN (\'PRADEEP\', \'P\') THEN \'PRADEEP\' WHEN UPPER(TRIM(spf.DONE_BY)) IN (\'BAJARANGI\', \'B\') THEN \'BAJARANGI\' WHEN UPPER(TRIM(spf.DONE_BY)) IN (\'RAMYA\', \'R\') THEN \'RAMYA\' WHEN UPPER(REPLACE(TRIM(spf.DONE_BY), \'’\', \'\')) IN (\'CHANDAN\', \'C\') THEN \'CHANDAN\' WHEN UPPER(REPLACE(TRIM(spf.DONE_BY), \'✓\', \'\')) IN (\'DHYAN\', \'D\',\'DHYAN\', \'DHYNA\', \'DHAYN\',\'DHYA\') THEN \'DHYAN\' ELSE NULL END AS fake_raised_by, r2i.REQUIRED_QTY, r2i.RECIEVED_QTY, r2i.REQUIRED_SKUS, r2i.RECEIVED_SKUS, NULLIF(LOWER(TRIM(spf.SALE_ORDER_CODE)), \'null\') AS SALE_ORDER_CODE, NULLIF(LOWER(TRIM(spf.ITEM_SKUCODE)), \'null\') AS ITEM_SKUCODE, spf.TOTAL_QTY, NULLIF(LOWER(TRIM(spf.PHY_SKU_CODE)), \'null\') AS PHY_SKU_CODE, NULLIF(LOWER(TRIM(spf.QC_COMMENT)), \'null\') AS QC_COMMENT, NULLIF(LOWER(TRIM(spf.remarks)), \'null\') AS remarks, NULLIF(LOWER(TRIM(r2i.QC_STATUS)), \'null\') AS QC_STATUS, NULLIF(LOWER(TRIM(r2i.QC_REMARKS)), \'null\') AS QC_REMARKS, NULLIF(LOWER(TRIM(spf.putaway_code)), \'null\') AS putaway_code, spf.TICKET_RAISED_BY as SPF_ticket_raised_by, TRY_TO_NUMBER(TRIM(spf.TICKET_NUMBER)) AS TICKET_NUMBER, NULLIF(UPPER(TRIM(spf.TICKET_STATUS)), \'null\') AS TICKET_STATUS, NULLIF(LOWER(TRIM(spf.REJECTION_REASON)), \'null\') AS REJECTION_REASON, COALESCE( TRY_TO_TIMESTAMP(spf.ticket_raised_date, \'MON DD, YYYY HH12:MI AM\'), TRY_TO_DATE(spf.ticket_raised_date, \'DD-MM-YYYY\') ) AS ticket_raised_ts, TO_DATE( TO_CHAR( COALESCE( TRY_TO_TIMESTAMP(spf.ticket_raised_date, \'MON DD, YYYY HH12:MI AM\'), TRY_TO_DATE(spf.ticket_raised_date, \'DD-MM-YYYY\')), \'YYYY-MM-DD\' ),\'YYYY-MM-DD\') AS ticket_raised_date, DATEDIFF( \'day\', TRY_TO_DATE(spf.received_date, \'DD-MM-YYYY\'),TO_DATE(TO_CHAR( COALESCE( TRY_TO_TIMESTAMP(spf.ticket_raised_date, \'MON DD, YYYY HH12:MI AM\'), TRY_TO_DATE(spf.ticket_raised_date, \'DD-MM-YYYY\')),\'YYYY-MM-DD\' ), \'YYYY-MM-DD\')) AS SPF_ageing, DATEDIFF( \'day\', TRY_TO_DATE(spf.received_date, \'DD-MM-YYYY\'),TO_DATE(TO_CHAR( COALESCE( TRY_TO_TIMESTAMP(r2i.qc_timestamp, \'MON DD, YYYY HH12:MI AM\'), TRY_TO_DATE(r2i.qc_timestamp, \'DD-MM-YYYY\')),\'YYYY-MM-DD\' ), \'YYYY-MM-DD\')) AS QC_ageing, concat(tracking_no, \'_\', item_skucode, \'_\' ) as concated_column1, ROW_NUMBER() OVER ( PARTITION BY UPPER(TRIM(concated_column1)) ORDER BY ticket_raised_date DESC NULLS LAST) - 1 AS concate1_duplicate_index, concat(tracking_no, \'_\', item_skucode, \'_\' , shipment_type ) as concated_column2, ROW_NUMBER() OVER ( PARTITION BY UPPER(TRIM(concated_column2)) ORDER BY ticket_raised_date DESC NULLS LAST) - 1 AS concate2_duplicate_index, TO_DATE(TO_CHAR(TO_TIMESTAMP_LTZ(TO_NUMBER(spf.last_updated_at) / 1000), \'DD-MM-YYYY\'), \'DD-MM-YYYY\') AS last_updated_at, FROM spf_fact_items_final_spf_table spf LEFT JOIN return_2_inwarding_data r2i ON spf.TRACKING_NO = r2i.AWB_NO;",
